def norm(s):
 m=min(r for r,c in s); n=min(c for r,c in s); return frozenset((r-m,c-n) for r,c in s)
def transforms(s):
 out=[]
 for k in range(4):
  t=[]
  for r,c in s:
   for _ in range(k): r,c=c,-r
   t.append((r,c))
  out.append(norm(t))
 return out
print([norm(x) for x in transforms(shapes['8'])]); print(norm(shapes['B']))

